\set ON_ERROR_STOP on
BEGIN;
DO $$ DECLARE
 p UUID:='f3100000-0000-4000-8000-000000000001';b UUID:='f3200000-0000-4000-8000-000000000001';u UUID:='f3300000-0000-4000-8000-000000000001';d UUID:='f3400000-0000-4000-8000-000000000001';pr UUID:='f3500000-0000-4000-8000-000000000001';ba UUID:='f3600000-0000-4000-8000-000000000001';s UUID:='f3700000-0000-4000-8000-000000000001';si UUID:='f3800000-0000-4000-8000-000000000001';op UUID:='f3900000-0000-4000-8000-000000000001';op2 UUID:='f3900000-0000-4000-8000-000000000002';nonce1 UUID:='f3a00000-0000-4000-8000-000000000001';nonce2 UUID:='f3a00000-0000-4000-8000-000000000002';nonce3 UUID:='f3a00000-0000-4000-8000-000000000003';nonce4 UUID:='f3a00000-0000-4000-8000-000000000004';h TEXT:=repeat('a',64);h2 TEXT:=repeat('b',64);r RECORD;caught BOOLEAN;
BEGIN
 IF EXISTS(SELECT 1 FROM public.pharmacies WHERE id=p) OR EXISTS(SELECT 1 FROM auth.users WHERE id=u OR email='pf-mvp10-financial@example.invalid') OR EXISTS(SELECT 1 FROM public.branches WHERE id=b) OR EXISTS(SELECT 1 FROM public.products WHERE id=pr) OR EXISTS(SELECT 1 FROM public.inventory_batches WHERE id=ba) OR EXISTS(SELECT 1 FROM public.sales WHERE id=s) OR EXISTS(SELECT 1 FROM public.sale_items WHERE id=si) THEN RAISE EXCEPTION 'PREEXISTING_FINANCIAL_FIXTURE';END IF;
 INSERT INTO auth.users(id,aud,role,email,created_at,updated_at)VALUES(u,'authenticated','authenticated','pf-mvp10-financial@example.invalid',now(),now());
 INSERT INTO public.pharmacies(id,name,owner_id)VALUES(p,'PF MVP10 Financial',u);INSERT INTO public.branches(id,pharmacy_id,name,is_main)VALUES(b,p,'Main',true);INSERT INTO public.pharmacy_members(user_id,pharmacy_id,role,default_branch_id,status)VALUES(u,p,'OWNER',b,'ACTIVE');
 INSERT INTO public.subscriptions(pharmacy_id,plan_code,status,current_period_start,current_period_end)VALUES(p,'TRIAL','ACTIVE',now()-interval '1 day',now()+interval '1 day');
 INSERT INTO public.devices(id,pharmacy_id,branch_id,registered_by,device_name,platform,public_key_pem,status)VALUES(d,p,b,u,'financial','WEB','pf-mvp10-key','ACTIVE');INSERT INTO public.products(id,pharmacy_id,name,selling_price)VALUES(pr,p,'Refund product',250);INSERT INTO public.inventory_batches(id,pharmacy_id,product_id,branch_id,batch_number,quantity,cost_price,selling_price)VALUES(ba,p,pr,b,'REFUND',10,1,250);
 INSERT INTO public.sales(id,pharmacy_id,branch_id,cashier_id,currency,subtotal,discount,tax,total,payment_method,amount_tendered,change_due,payment_status)VALUES(s,p,b,u,'NGN',500,0,0,500,'CASH',500,0,'SETTLED');INSERT INTO public.sale_items(id,sale_id,pharmacy_id,product_id,batch_id,quantity,unit_price,discount,tax,total)VALUES(si,s,p,pr,ba,2,250,0,0,500);
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);PERFORM set_config('request.jwt.claim.role','service_role',true);PERFORM set_config('request.headers',jsonb_build_object('x-pharmacyflow-actor-id','f3300000-0000-4000-8000-000000000099','x-pharmacyflow-pharmacy-id',p,'x-pharmacyflow-branch-id',b,'x-pharmacyflow-device-id',d,'x-pharmacyflow-operation-kind','SALE_REFUND','x-pharmacyflow-client-operation-id',op,'x-pharmacyflow-payload-fingerprint',h)::TEXT,true);
 caught:=FALSE;BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,op,nonce1,h,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','bad provenance');EXCEPTION WHEN insufficient_privilege THEN caught:=TRUE;END;IF NOT caught OR EXISTS(SELECT 1 FROM public.sale_returns WHERE pharmacy_id=p) THEN RAISE EXCEPTION 'OPERATOR_PROVENANCE_NOT_ENFORCED';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-pharmacyflow-actor-id',u,'x-pharmacyflow-pharmacy-id',p,'x-pharmacyflow-branch-id',b,'x-pharmacyflow-device-id',d,'x-pharmacyflow-operation-kind','SALE_REFUND','x-pharmacyflow-client-operation-id',op,'x-pharmacyflow-payload-fingerprint',h)::TEXT,true);
 SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,op,nonce1,h,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','acceptance');IF r.operation_status<>'COMMITTED' THEN RAISE EXCEPTION 'REFUND_NOT_COMMITTED';END IF;
 SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,op,nonce2,h,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','acceptance');IF r.operation_status<>'ALREADY_COMMITTED' THEN RAISE EXCEPTION 'REFUND_REPLAY_FAILED';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-pharmacyflow-actor-id',u,'x-pharmacyflow-pharmacy-id',p,'x-pharmacyflow-branch-id',b,'x-pharmacyflow-device-id',d,'x-pharmacyflow-operation-kind','SALE_REFUND','x-pharmacyflow-client-operation-id',op2,'x-pharmacyflow-payload-fingerprint',h2)::TEXT,true);
 caught:=FALSE;BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,op2,nonce1,h2,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','nonce reuse');EXCEPTION WHEN unique_violation THEN caught:=TRUE;END;IF NOT caught OR EXISTS(SELECT 1 FROM public.sync_journal WHERE pharmacy_id=p AND client_op_id=op2) THEN RAISE EXCEPTION 'REFUND_NONCE_REUSE_BOUNDARY_FAILED';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-pharmacyflow-actor-id',u,'x-pharmacyflow-pharmacy-id',p,'x-pharmacyflow-branch-id',b,'x-pharmacyflow-device-id',d,'x-pharmacyflow-operation-kind','SALE_REFUND','x-pharmacyflow-client-operation-id',op,'x-pharmacyflow-payload-fingerprint',h2)::TEXT,true);
 caught:=FALSE;BEGIN PERFORM * FROM public.rpc_process_sale_return_v2(u,p,b,d,op,nonce4,h2,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','changed');EXCEPTION WHEN unique_violation THEN caught:=TRUE;END;IF NOT caught OR EXISTS(SELECT 1 FROM public.sync_nonces WHERE nonce=nonce4) THEN RAISE EXCEPTION 'REFUND_CHANGED_PAYLOAD_BOUNDARY_FAILED';END IF;
 UPDATE public.subscriptions SET status='EXPIRED',current_period_start=now()-interval '9 days',current_period_end=now()-interval '8 days' WHERE pharmacy_id=p;
 PERFORM set_config('request.headers',jsonb_build_object('x-pharmacyflow-actor-id',u,'x-pharmacyflow-pharmacy-id',p,'x-pharmacyflow-branch-id',b,'x-pharmacyflow-device-id',d,'x-pharmacyflow-operation-kind','SALE_REFUND','x-pharmacyflow-client-operation-id',op,'x-pharmacyflow-payload-fingerprint',h)::TEXT,true);
 SELECT * INTO r FROM public.rpc_process_sale_return_v2(u,p,b,d,op,nonce3,h,s,jsonb_build_array(jsonb_build_object('sale_item_id',si,'quantity',1)),250,'CASH','acceptance');IF r.operation_status<>'ALREADY_COMMITTED' THEN RAISE EXCEPTION 'EXPIRED_REFUND_REPLAY_FAILED';END IF;
 IF (SELECT count(*) FROM public.sale_returns WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.return_items WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.sale_return_line_allocations WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.sync_journal WHERE pharmacy_id=p)<>1 OR (SELECT count(*) FROM public.sync_nonces WHERE pharmacy_id=p)<>3 OR (SELECT count(*) FROM public.entitlement_committed_operations_v1 WHERE pharmacy_id=p)<>1 OR (SELECT quantity FROM public.inventory_batches WHERE id=ba)<>11 THEN RAISE EXCEPTION 'REFUND_AUTHORITATIVE_EFFECT_MISMATCH';END IF;
END $$;
ROLLBACK;
SELECT 'PF_PASS|financial-refund-preservation';
